private List<Integer> getNanPositions(IntDoublePair[] ranks) {
    List<Integer> nanPositions = new ArrayList<Integer>();
    for (int i = 0; i < ranks.length; i++) {
        if (Double.isNaN(ranks[i].getValue())) {
            nanPositions.add(ranks[i].getPosition());
        }
    }
    return nanPositions;
}

